// region GraphQL custom fields

/*
 * The GraphQL schema is the same for every site; a custom field cannot be a
 * GraphQL field of its own, so it is read through an *accessor* typed by the
 * field's kind. For each content type this section has:
 *
 *   - `<Type>CustomFields`           the shape of the fragment's result;
 *   - `<Type>CustomFields.FRAGMENT`  a named GraphQL fragment to spread.
 *
 * A string, integer, float, boolean, date or datetime field is read as an
 * alias of its accessor (`price: customFloat(name: "price")`) and is typed
 * here. Every other kind (list, group, reference, media, geolocation, json)
 * has no scalar accessor, so those names are read together through
 * `fields(names: [...])`, which returns `KilnCustomFieldValue`s. Values
 * arrive under per-kind aliases (`asString`, `asInt`, ...) because GraphQL
 * forbids one response key with several types. The fragment goes one level
 * into lists and groups.
 *
 * A field that is unknown, deleted, private to the reader or of another
 * kind than the accessor is `null` (or absent from `fields`), so the server
 * never rejects a stale fragment. A dynamic content type is an `Entry`:
 * select its fragment on `publishedEntries(filter: {typeName: ...})`. The
 * names here are the site's definitions *now*: regenerate after an admin
 * changes them. Filtering and sorting still use `customFilter`/`customSort`.
 */

/** A custom-field value as `fields(names:)` returns it, told apart by `__typename`. */
@Serializable(with = KilnCustomFieldValueSerializer::class)
public sealed interface KilnCustomFieldValue {
    /** The custom field's name. */
    public val name: String

    @Serializable
    public data class StringValue(
        public override val name: String,
        @SerialName("asString") public val value: String,
    ) : KilnCustomFieldValue

    @Serializable
    public data class IntValue(
        public override val name: String,
        @SerialName("asInt") public val value: Long,
    ) : KilnCustomFieldValue

    @Serializable
    public data class FloatValue(
        public override val name: String,
        @SerialName("asFloat") public val value: Double,
    ) : KilnCustomFieldValue

    @Serializable
    public data class BooleanValue(
        public override val name: String,
        @SerialName("asBoolean") public val value: Boolean,
    ) : KilnCustomFieldValue

    @Serializable
    public data class DateValue(
        public override val name: String,
        @SerialName("asDate") public val value: String,
    ) : KilnCustomFieldValue

    @Serializable
    public data class DateTimeValue(
        public override val name: String,
        @SerialName("asDateTime") public val value: String,
    ) : KilnCustomFieldValue

    @Serializable
    public data class GeolocationValue(
        public override val name: String,
        public val lat: Double,
        public val lng: Double,
        public val label: String? = null,
        public val zoom: Double? = null,
    ) : KilnCustomFieldValue

    @Serializable
    public data class JsonValue(
        public override val name: String,
        @SerialName("asJson") public val value: String? = null,
    ) : KilnCustomFieldValue

    @Serializable
    public data class ReferenceValue(
        public override val name: String,
        public val ids: List<String>,
    ) : KilnCustomFieldValue

    @Serializable
    public data class MediaValue(
        public override val name: String,
        public val id: String,
        public val url: String? = null,
        public val alt: String? = null,
        public val width: Long? = null,
        public val height: Long? = null,
        public val mimeType: String? = null,
        public val focal: Focal? = null,
        public val variants: List<Variant> = emptyList(),
    ) : KilnCustomFieldValue {
        @Serializable
        public data class Focal(public val x: Double, public val y: Double)

        @Serializable
        public data class Variant(
            public val label: String? = null,
            public val width: Long? = null,
            public val height: Long? = null,
            public val format: String? = null,
            public val url: String? = null,
            public val bytes: Long? = null,
            public val cropped: Boolean? = null,
        )
    }

    @Serializable
    public data class ListValue(
        public override val name: String,
        public val items: List<KilnCustomFieldValue>,
    ) : KilnCustomFieldValue

    @Serializable
    public data class GroupValue(
        public override val name: String,
        public val fields: List<KilnCustomFieldValue>,
    ) : KilnCustomFieldValue

    /** A value kind this schema does not know — one added since it was generated. */
    public data class Unknown(
        public override val name: String,
        public val typename: String,
        public val raw: JsonObject,
    ) : KilnCustomFieldValue
}

/** Reads a [KilnCustomFieldValue] by its `__typename`; JSON only. */
public object KilnCustomFieldValueSerializer : KSerializer<KilnCustomFieldValue> {
    override val descriptor: SerialDescriptor = buildClassSerialDescriptor("KilnCustomFieldValue")

    override fun deserialize(decoder: Decoder): KilnCustomFieldValue {
        val input = decoder as? JsonDecoder ?: throw SerializationException("KilnCustomFieldValue decodes from JSON only")
        val raw = input.decodeJsonElement().jsonObject
        val fields = JsonObject(raw - "__typename")
        return when (val typename = (raw["__typename"] as? JsonPrimitive)?.contentOrNull) {
            "StringValue" -> input.json.decodeFromJsonElement(KilnCustomFieldValue.StringValue.serializer(), fields)
            "IntValue" -> input.json.decodeFromJsonElement(KilnCustomFieldValue.IntValue.serializer(), fields)
            "FloatValue" -> input.json.decodeFromJsonElement(KilnCustomFieldValue.FloatValue.serializer(), fields)
            "BooleanValue" -> input.json.decodeFromJsonElement(KilnCustomFieldValue.BooleanValue.serializer(), fields)
            "DateValue" -> input.json.decodeFromJsonElement(KilnCustomFieldValue.DateValue.serializer(), fields)
            "DateTimeValue" -> input.json.decodeFromJsonElement(KilnCustomFieldValue.DateTimeValue.serializer(), fields)
            "GeolocationValue" -> input.json.decodeFromJsonElement(KilnCustomFieldValue.GeolocationValue.serializer(), fields)
            "JsonValue" -> input.json.decodeFromJsonElement(KilnCustomFieldValue.JsonValue.serializer(), fields)
            "ReferenceValue" -> input.json.decodeFromJsonElement(KilnCustomFieldValue.ReferenceValue.serializer(), fields)
            "MediaValue" -> input.json.decodeFromJsonElement(KilnCustomFieldValue.MediaValue.serializer(), fields)
            "ListValue" -> input.json.decodeFromJsonElement(KilnCustomFieldValue.ListValue.serializer(), fields)
            "GroupValue" -> input.json.decodeFromJsonElement(KilnCustomFieldValue.GroupValue.serializer(), fields)
            else -> KilnCustomFieldValue.Unknown((raw["name"] as? JsonPrimitive)?.contentOrNull.orEmpty(), typename.orEmpty(), raw)
        }
    }

    override fun serialize(encoder: Encoder, value: KilnCustomFieldValue) {
        val output = encoder as? JsonEncoder ?: throw SerializationException("KilnCustomFieldValue encodes to JSON only")
        val raw = when (value) {
            is KilnCustomFieldValue.StringValue -> output.json.encodeToJsonElement(KilnCustomFieldValue.StringValue.serializer(), value).kilnTagged("StringValue")
            is KilnCustomFieldValue.IntValue -> output.json.encodeToJsonElement(KilnCustomFieldValue.IntValue.serializer(), value).kilnTagged("IntValue")
            is KilnCustomFieldValue.FloatValue -> output.json.encodeToJsonElement(KilnCustomFieldValue.FloatValue.serializer(), value).kilnTagged("FloatValue")
            is KilnCustomFieldValue.BooleanValue -> output.json.encodeToJsonElement(KilnCustomFieldValue.BooleanValue.serializer(), value).kilnTagged("BooleanValue")
            is KilnCustomFieldValue.DateValue -> output.json.encodeToJsonElement(KilnCustomFieldValue.DateValue.serializer(), value).kilnTagged("DateValue")
            is KilnCustomFieldValue.DateTimeValue -> output.json.encodeToJsonElement(KilnCustomFieldValue.DateTimeValue.serializer(), value).kilnTagged("DateTimeValue")
            is KilnCustomFieldValue.GeolocationValue -> output.json.encodeToJsonElement(KilnCustomFieldValue.GeolocationValue.serializer(), value).kilnTagged("GeolocationValue")
            is KilnCustomFieldValue.JsonValue -> output.json.encodeToJsonElement(KilnCustomFieldValue.JsonValue.serializer(), value).kilnTagged("JsonValue")
            is KilnCustomFieldValue.ReferenceValue -> output.json.encodeToJsonElement(KilnCustomFieldValue.ReferenceValue.serializer(), value).kilnTagged("ReferenceValue")
            is KilnCustomFieldValue.MediaValue -> output.json.encodeToJsonElement(KilnCustomFieldValue.MediaValue.serializer(), value).kilnTagged("MediaValue")
            is KilnCustomFieldValue.ListValue -> output.json.encodeToJsonElement(KilnCustomFieldValue.ListValue.serializer(), value).kilnTagged("ListValue")
            is KilnCustomFieldValue.GroupValue -> output.json.encodeToJsonElement(KilnCustomFieldValue.GroupValue.serializer(), value).kilnTagged("GroupValue")
