private fun JsonElement.kilnTagged(typename: String): JsonObject =
    JsonObject(jsonObject + ("__typename" to JsonPrimitive(typename)))

/** The result of [PostCustomFields.FRAGMENT] — the site's custom fields. On `Post`. */
@Serializable
